**What this code covers**

- Abstract base class for LLM backends.
- Send messages and return a dict with 'content' and 'tool_calls'.
- Stream responses token by token.
- OpenAI API backend (also works with Azure OpenAI and compatible APIs).
- Anthropic uses a different message format — adapt
- Anthropic expects tool results as user messages with tool_result
- Swap backends by changing one line:

**Defines:** `LLMBackend`, `OpenAIBackend`, `AnthropicBackend`, `OllamaBackend`, `call_llamacpp()`, `main()`

One major advantage of building from scratch: swapping the LLM backend is trivial.

### Abstract LLM Backend

```python
from abc import ABC, abstractmethod
from typing import Generator

class LLMBackend(ABC):
    """Abstract base class for LLM backends."""

    @abstractmethod
    def chat(self, messages: list[dict], tools: list[dict] | None = None, **kwargs) -> dict:
        """Send messages and return a dict with 'content' and 'tool_calls'."""
        ...

    def stream(self, messages: list[dict], **kwargs) -> Generator[str, None, None]:
        """Stream responses token by token. Override for streaming support."""
        result = self.chat(messages, **kwargs)
        yield result["content"]

class OpenAIBackend(LLMBackend):
    """OpenAI API backend (also works with Azure OpenAI and compatible APIs)."""

    def __init__(self, model: str = "gpt-4o", api_key: str | None = None, base_url: str | None = None):
        from openai import OpenAI
        kwargs = {}
        if api_key:
            kwargs["api_key"] = api_key
        if base_url:
            kwargs["base_url"] = base_url
        self.client = OpenAI(**kwargs)
        self.model = model

    def chat(self, messages, tools=None, **kwargs):
        params = {"model": self.model, "messages": messages, **kwargs}
        if tools:
            params["tools"] = tools
        response = self.client.chat.completions.create(**params)
        msg = response.choices[0].message
        return {
            "content": msg.content,
            "tool_calls": [
                {"id": tc.id, "name": tc.function.name, "arguments": tc.function.arguments}
                for tc in (msg.tool_calls or [])
            ],
            "usage": {
                "prompt_tokens": response.usage.prompt_tokens if response.usage else 0,
                "completion_tokens": response.usage.completion_tokens if response.usage else 0,
            },
        }

class AnthropicBackend(LLMBackend):
    """Anthropic Claude API backend."""

    def __init__(self, model: str = "claude-sonnet-4-20250514", api_key: str | None = None):
        import anthropic
        self.client = anthropic.Anthropic(api_key=api_key)
        self.model = model

    def chat(self, messages, tools=None, **kwargs):
        # Anthropic uses a different message format — adapt
        system_msg = ""
        chat_msgs = []
        for m in messages:
            if m["role"] == "system":
                system_msg = m["content"]
            elif m["role"] == "tool":
                # Anthropic expects tool results as user messages with tool_result
                chat_msgs.append({
                    "role": "user",
                    "content": [{
                        "type": "tool_result",
                        "tool_use_id": m["tool_call_id"],
                        "content": m["content"],
                    }],
                })
            elif m["role"] == "assistant" and m.get("tool_calls"):
                content = []
                if m.get("content"):
                    content.append({"type": "text", "text": m["content"]})
                for tc in m["tool_calls"]:
                    content.append({
                        "type": "tool_use",
                        "id": tc["id"],
                        "name": tc["name"],
                        "input": json.loads(tc["arguments"]),
                    })
                chat_msgs.append({"role": "assistant", "content": content})
            else:
                chat_msgs.append(m)

        params = {"model": self.model, "messages": chat_msgs, "max_tokens": 4096, **kwargs}
        if system_msg:
            params["system"] = system_msg
        if tools:
            params["tools"] = [
                {"name": t["function"]["name"],
                 "description": t["function"]["description"],
                 "input_schema": t["function"]["parameters"]}
                for t in tools
            ]

        response = self.client.messages.create(**params)
        content = response.content
        text_parts = [c.text for c in content if c.type == "text"]
        tool_parts = [c for c in content if c.type == "tool_use"]

        return {
            "content": "\n".join(text_parts) if text_parts else None,
            "tool_calls": [
                {"id": t.id, "name": t.name, "arguments": json.dumps(t.input)}
                for t in tool_parts
            ],
            "usage": {
                "prompt_tokens": response.usage.input_tokens,
                "completion_tokens": response.usage.output_tokens,
            },
        }

class OllamaBackend(LLMBackend):
    """Ollama local model backend using the OpenAI-compatible API."""

    def __init__(self, model: str = "llama3.1", base_url: str = "http://localhost:11434/v1"):
        from openai import OpenAI
        self.client = OpenAI(base_url=base_url, api_key="ollama")  # Ollama doesn't need a key
        self.model = model

    def chat(self, messages, tools=None, **kwargs):
        params = {"model": self.model, "messages": messages, **kwargs}
        if tools:
            params["tools"] = tools
        response = self.client.chat.completions.create(**params)
        msg = response.choices[0].message
        return {
            "content": msg.content,
            "tool_calls": [
                {"id": tc.id, "name": tc.function.name, "arguments": tc.function.arguments}
                for tc in (msg.tool_calls or [])
            ],
            "usage": {
                "prompt_tokens": response.usage.prompt_tokens if response.usage else 0,
                "completion_tokens": response.usage.completion_tokens if response.usage else 0,
            },
        }

# --- Using the abstraction ---

# Swap backends by changing one line:
# backend = OpenAIBackend(model="gpt-4o")
# backend = AnthropicBackend(model="claude-sonnet-4-20250514")
backend = OllamaBackend(model="llama3.1")

result = backend.chat([
    {"role": "system", "content": "You are a helpful assistant."},
    {"role": "user", "content": "What is the capital of France?"},
])
print(result["content"])
```

### Using `httpx` for Async Calls to a Local llama.cpp Server

```python
import asyncio
import httpx

async def call_llamacpp(
    prompt: str,
    model_url: str = "http://localhost:8080/completion",
    temperature: float = 0.7,
    max_tokens: int = 512,
) -> str:
    """Async call to a llama.cpp server using httpx."""
    async with httpx.AsyncClient(timeout=120.0) as client:
        response = await client.post(
            model_url,
            json={
                "prompt": prompt,
                "temperature": temperature,
                "n_predict": max_tokens,
                "stop": ["</s>"],
            },
        )
        response.raise_for_status()
        data = response.json()
        return data.get("content", "")

async def main():
    answer = await call_llamacpp("What is machine learning? Explain in one sentence.")
    print(f"llama.cpp: {answer}")

# asyncio.run(main())
```
